return {
  getRadialItems() {
    return [{
      label: 'Explode',
      isEnabled: () => true,
      onSelect: () => {
        ctx.particles.burst({ color: '#f97316', count: 50, durationMs: 900 });
        ctx.world.deleteSelf();
      }
    }];
  }
};

let pivot = null;
let restY = 0;
const HALF_WIDTH = 0.4;
const MIN_ANGLE = -Math.PI * 0.55;
const MAX_ANGLE = 0;

return {
  onSpawn() {
    // Runs identically on every peer at spawn time, so the hinge geometry
    // is always consistent even for bystanders who never grab the door.
    const pos = ctx.self.getWorldPosition();
    restY = pos[1];
    pivot = [pos[0] - HALF_WIDTH, pos[1], pos[2]];
  },
  tick() {
    if (!ctx.grab.isHeld()) return;
    const p = ctx.self.getWorldPosition();
    let angle = Math.atan2(p[2] - pivot[2], p[0] - pivot[0]);
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    // Overrides whatever the raw (free 6DOF) grab-follow produced this
    // frame with a position/rotation constrained to swing only around the
    // hinge pivot, on a single (Y) axis, clamped to a believable range.
    ctx.self.setWorldPosition([
      pivot[0] + Math.cos(angle) * HALF_WIDTH,
      restY,
      pivot[2] + Math.sin(angle) * HALF_WIDTH
    ]);
    ctx.self.setWorldRotation(ctx.math.quatFromAxisAngle([0, 1, 0], angle));
  }
};

let pivot = null;
let isOn = false;
const ON_COLOR = '#facc15';
const OFF_COLOR = '#374151';
const RADIUS = 0.22;
const RANGE = Math.PI / 6;

return {
  onSpawn() {
    pivot = ctx.self.getWorldPosition();
  },
  tick() {
    if (!ctx.grab.isHeld()) return;
    const p = ctx.self.getWorldPosition();
    let angle = Math.atan2(p[1] - pivot[1], p[0] - pivot[0]);
    if (angle > RANGE) angle = RANGE;
    if (angle < -RANGE) angle = -RANGE;
    ctx.self.setWorldPosition([
      pivot[0] + Math.cos(angle) * RADIUS,
      pivot[1] + Math.sin(angle) * RADIUS,
      pivot[2]
    ]);
    ctx.self.setWorldRotation(ctx.math.quatFromAxisAngle([0, 0, 1], angle));
    isOn = angle > 0;
  },
  onRelease() {
    // Cross-object mutation: host/solo-only (see setComponentField's doc
    // comment) — a guest flipping the switch is a documented no-op, self-
    // corrected by the next broadcast, same as every other guest-triggered
    // mutation in this app.
    const bulb = ctx.hierarchy.findByName('Light Bulb');
    if (bulb) ctx.world.setComponentField(bulb.id, 'meshRenderer', 'color', isOn ? ON_COLOR : OFF_COLOR);
  }
};

let velocity = [0, 0, 0];
let previousPosition = null;
const GRAVITY = -9.81;
const RADIUS = 0.09;
const BOUNCE = 0.78;
const FRICTION = 0.86;
const MAX_THROW_SPEED = 8;
const REST_SPEED = 0.45;

function clampThrowSpeed(v) {
  const speed = ctx.math.vecLength(v);
  if (speed <= MAX_THROW_SPEED) return v;
  return ctx.math.vecScale(ctx.math.vecNormalize(v), MAX_THROW_SPEED);
}

return {
  onSpawn() {
    previousPosition = ctx.self.getWorldPosition();
  },
  onGrab() {
    velocity = [0, 0, 0];
    previousPosition = ctx.self.getWorldPosition();
  },
  tick(dt) {
    const safeDt = Math.min(Math.max(dt, 1 / 120), 1 / 20);
    const position = ctx.self.getWorldPosition();

    // Every peer measures the hand motion so a local release has a useful
    // throw velocity. Only the host advances the free-flight simulation.
    if (ctx.grab.isHeld()) {
      if (previousPosition) {
        velocity = clampThrowSpeed(ctx.math.vecScale(
          ctx.math.vecSub(position, previousPosition),
          1 / safeDt
        ));
      }
      previousPosition = position;
      return;
    }

    previousPosition = position;
    if (!ctx.world.isHost()) return;

    velocity[1] += GRAVITY * safeDt;
    const nextPosition = ctx.math.vecAdd(position, ctx.math.vecScale(velocity, safeDt));
    if (nextPosition[1] <= RADIUS) {
      nextPosition[1] = RADIUS;
      if (velocity[1] < 0) velocity[1] = -velocity[1] * BOUNCE;
      velocity[0] *= FRICTION;
      velocity[2] *= FRICTION;
      if (velocity[1] < REST_SPEED) velocity[1] = 0;
    }

    ctx.self.setWorldPosition(nextPosition);
  },
  getRadialItems() {
    return [{
      label: 'Reset Ball',
      isEnabled: () => ctx.world.isHost(),
      onSelect: () => {
        velocity = [0, 0, 0];
        ctx.self.setWorldPosition([-1.1, 1.35, -1.2]);
      }
    }];
  }
};

let spawnPos = null;
let spawnRot = null;
let previousPosition = null;
let velocity = [0, 0, 0];
let currentThrower = null; // { id, name } captured at grab time
let hitPinsThisThrow = new Set();
let lastResetSeen = 0;

// Sits at the spawn point doing nothing until grabbed — without this, the
// very first tick (and every tick right after a return finishes) would see
// "grounded, ~zero velocity" and immediately think the throw is over,
// triggering startReturn() again forever.
let atRest = true;
let elapsedSinceRelease = 0;
const MIN_ROLL_TIME = 0.35; // don't call it "stopped" before it's had a moment to actually roll

const GRAVITY = -9.81;
const LANE_SURFACE_Y = 0.06;
const BALL_RADIUS = 0.11;
const ROLL_FRICTION = 0.35;
const STOP_SPEED = 0.05;
const MAX_THROW_SPEED = 6;
const HIT_RADIUS = 0.16;
const PIN_IMPULSE = 1.8;
const PIT_Z = -6.6; // past the last pin row — falling off the end starts the return
const FRAME_COUNT = 10;

// --- ball-return rail: a simulated 3-leg path back to the start, like a
// real bowling alley's mechanical return, so the ball never needs to be
// walked back by hand. Timed to feel like an actual mechanism, not a snap. ---
const RAIL_X_OFFSET = -0.65;
const RAIL_Y = 0.02;
const DROP_DURATION = 0.6;
const RISE_DURATION = 0.6;
const RAIL_SPEED = 1.1;

let returning = false;
let returnLegs = [];
let returnLegIndex = 0;
let returnT = 0;

function lerpVec(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function findSiblings() {
  const parent = ctx.hierarchy.getParent(ctx.self.id);
  return parent ? ctx.hierarchy.getChildren(parent.id) : [];
}

function getScoreState(scoreboard) {
  const comp = scoreboard.components.find((c) => c.type === 'scriptState');
  return (comp && comp.data) || {};
}

function sumTurns(turns) {
  return turns.reduce((a, b) => a + b, 0);
}

// Recomputes the scoreboard's visible grid (columns/rows/status) from the
// raw turn-history state — the scoreboard component only knows how to lay
// out a grid, all the bowling-specific meaning is built here.
function renderBoard(scoreboard, state) {
  const columns = [];
  for (let i = 1; i <= FRAME_COUNT; i++) columns.push(String(i));
  columns.push('Total');

  const players = Object.values(state.players || {});
  const sorted = [...players].sort((a, b) => sumTurns(b.turns) - sumTurns(a.turns));
  const leaderTotal = sorted.length > 0 ? sumTurns(sorted[0].turns) : -1;

  const rows = sorted.map((p) => {
    const recentTurns = p.turns.slice(-FRAME_COUNT);
    const blanks = Array(FRAME_COUNT - recentTurns.length).fill('');
    const total = sumTurns(p.turns);
    return {
      name: p.name,
      cells: [...blanks, ...recentTurns.map(String), String(total)],
      highlight: state.playerName === p.name,
      isLeader: total > 0 && total === leaderTotal
    };
  });

  const status = state.playerName ? `Up: ${state.playerName} — throw ${state.throwsThisTurn + 1}/2` : 'Grab the ball to play!';

  ctx.world.setComponentField(scoreboard.id, 'scoreboard', 'columns', columns);
  ctx.world.setComponentField(scoreboard.id, 'scoreboard', 'rows', rows);
  ctx.world.setComponentField(scoreboard.id, 'scoreboard', 'status', status);
}

// Ends the current throw: scores it against whoever grabbed the ball,
// registering them on the scoreboard if this is their first throw, and
// resets the pins once a turn (2 throws, or a strike) is complete.
function finishThrow() {
  if (!ctx.world.isHost() || !currentThrower) return;
  const siblings = findSiblings();
  const scoreboard = siblings.find((s) => s.name === 'Scoreboard');
  if (!scoreboard) return;

  const knocked = hitPinsThisThrow.size;
  const state = getScoreState(scoreboard);
  const players = { ...(state.players || {}) };
  const existing = players[currentThrower.id] || { name: currentThrower.name, turns: [] };

  const isSameTurnPlayer = state.playerId === currentThrower.id;
  const pendingFirstThrow = isSameTurnPlayer ? state.pendingFirstThrow || 0 : 0;
  const throwsThisTurn = isSameTurnPlayer ? (state.throwsThisTurn || 0) + 1 : 1;
  const turnDone = knocked >= 10 || throwsThisTurn >= 2;

  const turns = turnDone ? [...existing.turns, pendingFirstThrow + knocked] : existing.turns;
  players[currentThrower.id] = { name: currentThrower.name, turns };

  const nextState = {
    players,
    throwsThisTurn: turnDone ? 0 : throwsThisTurn,
    playerId: turnDone ? null : currentThrower.id,
    playerName: turnDone ? null : currentThrower.name,
    pendingFirstThrow: turnDone ? 0 : knocked
  };
  ctx.world.setComponentField(scoreboard.id, 'scriptState', 'data', nextState);
  renderBoard(scoreboard, nextState);

  if (knocked >= 10) {
    // strike — a bigger crash than a normal pin knock
    ctx.audio.play({ noiseMix: 1, durationMs: 500, volume: 0.7 });
  }

  if (turnDone) {
    const now = Date.now();
    for (const s of siblings) {
      if (s.name.startsWith('Pin ')) ctx.world.setComponentField(s.id, 'scriptState', 'data', { resetRequestedAt: now });
    }
  }
  currentThrower = null;
}

function startReturn(fromPos) {
  finishThrow();
  const railX = spawnPos[0] + RAIL_X_OFFSET;
  const dropTo = [railX, RAIL_Y, fromPos[2]];
  const travelTo = [railX, RAIL_Y, spawnPos[2]];
  const travelDist = Math.abs(dropTo[2] - travelTo[2]);
  returnLegs = [
    { from: fromPos, to: dropTo, duration: DROP_DURATION },
    { from: dropTo, to: travelTo, duration: Math.max(travelDist / RAIL_SPEED, 0.3) },
    { from: travelTo, to: spawnPos, duration: RISE_DURATION }
  ];
  returnLegIndex = 0;
  returnT = 0;
  returning = true;
  velocity = [0, 0, 0];
}

return {
  onSpawn() {
    spawnPos = ctx.self.getWorldPosition();
    spawnRot = ctx.self.getWorldRotation();
    previousPosition = spawnPos;
  },
  onGrab() {
    const holders = ctx.grab.heldBy();
    if (holders.length > 0) currentThrower = ctx.world.getPlayer(holders[0]);
    hitPinsThisThrow = new Set();
    returning = false;
    atRest = false;
    elapsedSinceRelease = 0;
    previousPosition = ctx.self.getWorldPosition();
  },
  tick(dt) {
    const safeDt = Math.min(Math.max(dt, 1 / 120), 1 / 20);

    // An external reset (the reset button, or a fresh turn) wins over
    // whatever this ball was doing, as long as nobody's currently holding it.
    const stateComp = ctx.self.getComponent('scriptState');
    const resetAt = stateComp && stateComp.data && stateComp.data.resetRequestedAt;
    if (resetAt && resetAt !== lastResetSeen && !ctx.grab.isHeld()) {
      lastResetSeen = resetAt;
      returning = false;
      atRest = true;
      velocity = [0, 0, 0];
      hitPinsThisThrow = new Set();
      currentThrower = null;
      ctx.self.setWorldPosition(spawnPos);
      ctx.self.setWorldRotation(spawnRot);
      previousPosition = spawnPos;
      return;
    }

    const position = ctx.self.getWorldPosition();

    // Every peer measures the hand motion so a local release has a useful
    // throw velocity. Only the host advances the simulation once released.
    if (ctx.grab.isHeld()) {
      velocity = ctx.math.vecScale(ctx.math.vecSub(position, previousPosition), 1 / safeDt);
      const speed = ctx.math.vecLength(velocity);
      if (speed > MAX_THROW_SPEED) velocity = ctx.math.vecScale(ctx.math.vecNormalize(velocity), MAX_THROW_SPEED);
      previousPosition = position;
      return;
    }
    previousPosition = position;
    if (!ctx.world.isHost()) return;

    if (returning) {
      const leg = returnLegs[returnLegIndex];
      returnT += safeDt;
      const t = Math.min(returnT / leg.duration, 1);
      ctx.self.setWorldPosition(lerpVec(leg.from, leg.to, t));
      if (t >= 1) {
        returnLegIndex += 1;
        returnT = 0;
        if (returnLegIndex >= returnLegs.length) {
          returning = false;
          atRest = true;
          ctx.self.setWorldRotation(spawnRot);
          ctx.audio.play({ frequency: 100, pitchDrop: 40, noiseMix: 0.4, durationMs: 150, volume: 0.35 });
        }
      }
      return;
    }

    // Sitting idle at the spawn point (initial load, or just finished
    // returning) — nothing to simulate until it's grabbed again.
    if (atRest) return;

    elapsedSinceRelease += safeDt;

    // free flight + rolling — real gravity so a release mid-air actually
    // falls to the lane instead of hovering at release height
    velocity[1] += GRAVITY * safeDt;
    const next = ctx.math.vecAdd(position, ctx.math.vecScale(velocity, safeDt));
    const grounded = next[1] <= LANE_SURFACE_Y + BALL_RADIUS;
    if (grounded) {
      next[1] = LANE_SURFACE_Y + BALL_RADIUS;
      velocity[1] = 0;
      velocity[0] *= 1 - ROLL_FRICTION * safeDt;
      velocity[2] *= 1 - ROLL_FRICTION * safeDt;
    }
    ctx.self.setWorldPosition(next);

    if (next[2] <= PIT_Z) {
      startReturn(next);
      return;
    }
    if (grounded && elapsedSinceRelease > MIN_ROLL_TIME && ctx.math.vecLength([velocity[0], 0, velocity[2]]) < STOP_SPEED) {
      startReturn(next);
      return;
    }

    // sphere-vs-pin hit detection via the generic spatial query
    for (const other of ctx.world.findNear(next, HIT_RADIUS)) {
      if (other.id === ctx.self.id || !other.name.startsWith('Pin ')) continue;
      if (!hitPinsThisThrow.has(other.id)) {
        hitPinsThisThrow.add(other.id);
        ctx.audio.play({ frequency: 180, pitchDrop: 60, noiseMix: 0.55, durationMs: 180, volume: 0.5 });
      }
      const dir = ctx.math.vecNormalize([other.position[0] - next[0], 0, other.position[2] - next[2]]);
      ctx.world.setComponentField(other.id, 'velocity', 'linear', ctx.math.vecScale(dir, PIN_IMPULSE));
    }
  },
  getRadialItems() {
    return [{
      label: 'Reset Ball',
      isEnabled: () => true,
      onSelect: () => {
        returning = false;
        atRest = true;
        velocity = [0, 0, 0];
        hitPinsThisThrow = new Set();
        currentThrower = null;
        ctx.self.setWorldPosition(spawnPos);
        ctx.self.setWorldRotation(spawnRot);
      }
    }];
  }
};

let spawnPos = null;
let spawnRot = null;
let fallAmount = 0;
let fallAxis = [1, 0, 0];
let lastResetSeen = 0;
const FALL_SPEED = 3.5;
const SETTLE_SPEED = 0.03;

return {
  onSpawn() {
    spawnPos = ctx.self.getWorldPosition();
    spawnRot = ctx.self.getWorldRotation();
  },
  tick(dt) {
    // The ball (or the reset button) signals a reset by writing a fresh
    // timestamp here — scripts can't call each other directly, so this
    // component field is the pub/sub channel (see types.ts's scriptState doc).
    const stateComp = ctx.self.getComponent('scriptState');
    const resetAt = stateComp && stateComp.data && stateComp.data.resetRequestedAt;
    if (resetAt && resetAt !== lastResetSeen && !ctx.grab.isHeld()) {
      lastResetSeen = resetAt;
      fallAmount = 0;
      ctx.world.setComponentField(ctx.self.id, 'velocity', 'linear', [0, 0, 0]);
      ctx.self.setWorldPosition(spawnPos);
      ctx.self.setWorldRotation(spawnRot);
      return;
    }

    if (ctx.grab.isHeld()) {
      fallAmount = 0;
      ctx.world.setComponentField(ctx.self.id, 'velocity', 'linear', [0, 0, 0]);
      return;
    }

    const comp = ctx.self.getComponent('velocity');
    const v = comp ? comp.linear : [0, 0, 0];
    const speed = ctx.math.vecLength(v);
    if (speed <= SETTLE_SPEED) return;

    // capture the fall axis once, from the hit direction, then keep tipping
    // toward it even as the (host-integrated) velocity keeps decaying
    if (fallAmount === 0) {
      const horizontal = ctx.math.vecNormalize([v[0], 0, v[2]]);
      fallAxis = ctx.math.vecCross([0, 1, 0], horizontal);
    }
    fallAmount = Math.min(fallAmount + dt * FALL_SPEED, 1);
    ctx.self.setWorldRotation(ctx.math.quatFromAxisAngle(fallAxis, fallAmount * (Math.PI / 2)));
  },
  getRadialItems() {
    return [{
      label: 'Stand Up',
      isEnabled: () => fallAmount > 0.05,
      onSelect: () => {
        fallAmount = 0;
        ctx.world.setComponentField(ctx.self.id, 'velocity', 'linear', [0, 0, 0]);
        ctx.self.setWorldPosition(spawnPos);
        ctx.self.setWorldRotation(spawnRot);
      }
    }];
  }
};

