const MAX_POWER = 6;
const MIN_POWER = 0.45;
const RETURN_TIME = 0.32;
const ARM_DISTANCE = 0.85;
const MIN_STROKE_SPEED = 0.1;
let spawnPos = null;
let spawnRot = null;
let previousPosition = null;
let maxStrokeSpeed = 0;
let strokeArmed = false;
let returning = false;
let returnFrom = null;
let returnT = 0;

function siblings() {
  const parent = ctx.hierarchy.getParent(ctx.self.id);
  return parent ? ctx.hierarchy.getChildren(parent.id) : [];
}

function parentSlot() {
  const parent = ctx.hierarchy.getParent(ctx.self.id);
  return parent || null;
}

function siblingWorldPosition(slot) {
  const parent = parentSlot();
  const scale = parent ? parent.scale : [1, 1, 1];
  const offset = parent ? parent.position : [0, 0, 0];
  return [
    offset[0] + slot.position[0] * scale[0],
    offset[1] + slot.position[1] * scale[1],
    offset[2] + slot.position[2] * scale[2]
  ];
}

function cueBall() {
  return siblings().find((slot) => slot.name === 'Cue Ball');
}

function scoreboard() {
  return siblings().find((slot) => slot.name === 'Pool Scoreboard');
}

function setStatus(message, player) {
  const board = scoreboard();
  if (!board) return;
  const component = board.components.find((candidate) => candidate.type === 'scriptState');
  const previous = (component && component.data) || {};
  const next = {
    ...previous,
    currentPlayerId: player ? player.id : previous.currentPlayerId,
    currentPlayerName: player ? player.name : previous.currentPlayerName,
    lastShot: message
  };
  ctx.world.setComponentField(board.id, 'scriptState', 'data', next);
  ctx.world.setComponentField(board.id, 'scoreboard', 'status', message);
}

function aimAtCue(stickPosition, cuePosition) {
  const direction = ctx.math.vecNormalize([cuePosition[0] - stickPosition[0], 0, cuePosition[2] - stickPosition[2]]);
  const yaw = Math.atan2(direction[0], direction[2]);
  return {
    direction,
    rotation: [0, Math.sin(yaw / 2), 0, Math.cos(yaw / 2)]
  };
}

function lerp(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function returnToRack() {
  returning = true;
  returnFrom = ctx.self.getWorldPosition();
  returnT = 0;
}

return {
  onSpawn() {
    spawnPos = ctx.self.getWorldPosition();
    spawnRot = ctx.self.getWorldRotation();
  },
  onGrab() {
    returning = false;
    maxStrokeSpeed = 0;
    strokeArmed = false;
    previousPosition = ctx.self.getWorldPosition();
    const holders = ctx.grab.heldBy();
    if (holders.length) {
      const player = ctx.world.getPlayer(holders[0]);
      setStatus(player.name + ' is aiming — place the cue, pull back, then release to shoot.', player);
    }
  },
  onRelease() {
    if (!ctx.world.isHost()) {
      returnToRack();
      return;
    }
    const cue = cueBall();
    const stickPosition = ctx.self.getWorldPosition();
    const cuePosition = cue ? siblingWorldPosition(cue) : null;
    if (!cue || !cuePosition) {
      returnToRack();
      return;
    }
    const cueState = cue.components.find((candidate) => candidate.type === 'scriptState');
    const cueVelocity = cue.components.find((candidate) => candidate.type === 'velocity');
    if (cueState && cueState.data && cueState.data.pocketed) {
      setStatus('Cue ball is pocketed — reset it before shooting again.');
      returnToRack();
      return;
    }
    if (cueVelocity && ctx.math.vecLength([cueVelocity.linear[0], 0, cueVelocity.linear[2]]) > MIN_STROKE_SPEED) {
      setStatus('Wait for the balls to stop before taking another shot.');
      returnToRack();
      return;
    }
    if (!strokeArmed || maxStrokeSpeed < MIN_STROKE_SPEED) {
      setStatus('Place the cue near the white ball, pull back, and release to set power.');
      returnToRack();
      return;
    }
    const aim = aimAtCue(stickPosition, cuePosition);
    const power = Math.min(Math.max(maxStrokeSpeed * 1.7, MIN_POWER), MAX_POWER);
    ctx.world.setComponentField(cue.id, 'velocity', 'linear', [aim.direction[0] * power, 0, aim.direction[2] * power]);
    setStatus('Shot power: ' + power.toFixed(1), null);
    ctx.audio.play({ frequency: 285, pitchDrop: 110, noiseMix: 0.42, durationMs: 115, volume: 0.34 });
    returnToRack();
  },
  tick(dt) {
    const safeDt = Math.min(Math.max(dt, 1 / 120), 1 / 30);
    if (ctx.grab.isHeld()) {
      returning = false;
      const current = ctx.self.getWorldPosition();
      const cue = cueBall();
      if (cue) {
        const cuePosition = siblingWorldPosition(cue);
        const distanceToCue = Math.hypot(current[0] - cuePosition[0], current[2] - cuePosition[2]);
        if (!strokeArmed && distanceToCue <= ARM_DISTANCE) {
          strokeArmed = true;
          maxStrokeSpeed = 0;
          previousPosition = current;
        } else if (strokeArmed && previousPosition) {
          const movement = ctx.math.vecScale(ctx.math.vecSub(current, previousPosition), 1 / safeDt);
          maxStrokeSpeed = Math.max(maxStrokeSpeed, ctx.math.vecLength([movement[0], 0, movement[2]]));
        }
        previousPosition = current;
        ctx.self.setWorldRotation(aimAtCue(current, cuePosition).rotation);
      } else {
        previousPosition = current;
      }
      return;
    }
    if (!returning) return;
    returnT += safeDt;
    const t = Math.min(returnT / RETURN_TIME, 1);
    ctx.self.setWorldPosition(lerp(returnFrom, spawnPos, t));
    ctx.self.setWorldRotation(spawnRot);
    if (t >= 1) returning = false;
  },
  getRadialItems() {
    return [{
      label: 'Return Cue',
      isEnabled: () => !ctx.grab.isHeld(),
      onSelect: () => {
        ctx.self.setWorldPosition(spawnPos);
        ctx.self.setWorldRotation(spawnRot);
        returning = false;
      }
    }];
  }
};
